// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes32 role, address actor) public {
        // The constructor grants roles only to the deployer (this test contract)
        // and the contract itself; any other address has no roles at all.
        vm.assume(actor != address(this));
        vm.assume(actor != address(c));
        // Admissible universal rule: an address never granted `role` is NOT a member of it.
        assertTrue(
            c.hasRole(role, actor) == false,
            "an address never granted a role must not be a member of that role"
        );
    }
}
